{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.return_2_inwarding_data AS (SELECT * FROM snitch_db.maplemonk.b2c_return_inward_inwarding_data); CREATE OR REPLACE TABLE ylk_b2c_returns AS SELECT COALESCE(yi.awb_no, ypd.awb) AS awb, TRY_TO_DATE(ypd.date, \'DD-MM-YYYY\') AS courier_partner_date, ypd.type, NULLIF(yi.TYPE,\'\') AS WH_TYPE, LOWER(ypd.source) AS source, TRY_TO_DATE(yi.receiving_date, \'DD-MM-YYYY\') AS receiving_date, COALESCE(TRY_TO_TIMESTAMP(ypd.inwarded_at, \'MON DD, YYYY HH12:MI AM\'), TRY_TO_DATE(ypd.inwarded_at, \'DD-MM-YYYY\')) AS inwarded_at, COALESCE(TRY_TO_TIMESTAMP(yi.scanning_date, \'MON DD, YYYY HH12:MI AM\'), TRY_TO_DATE(yi.scanning_date, \'DD-MM-YYYY\')) AS scanning_date, COALESCE(TRY_TO_TIMESTAMP(ypd.qc_completed_at, \'DD-MM-YYYY HH24:MI\'), TRY_TO_TIMESTAMP(ypd.qc_completed_at, \'DD-MM-YYYY HH24:MI:SS\'), TRY_TO_TIMESTAMP(ypd.qc_completed_at, \'YYYY-MM-DD HH24:MI:SS\')) AS qc_completed_at, COALESCE(TRY_TO_TIMESTAMP(TRIM(TOTE_NUMBER), \'YYYY-MM-DD HH24:MI:SS\'), TRY_TO_TIMESTAMP(TRIM(TOTE_NUMBER), \'YYYY-MM-DD HH24:MI\'), TRY_TO_TIMESTAMP(TRIM(TOTE_NUMBER), \'DD-MM-YYYY HH24:MI:SS\'), TRY_TO_TIMESTAMP(TRIM(TOTE_NUMBER), \'DD-MM-YYYY HH24:MI\')) AS tote_ts, TRY_TO_TIMESTAMP(yi.qc_timestamp, \'MON DD, YYYY HH12:MI AM\') AS qc_timestamp, TRY_TO_TIME(RTRIM(SPLIT_PART(QC_TIMESTAMP, \' \', 4) || \' \' || SPLIT_PART(QC_TIMESTAMP, \' \', 5))) AS QC_TIME, ypd.last_updated_at, yi.chanel AS channel, yi.lm_patner AS lm_partner, yi.packet_no, yi.qc_status, yi.qc_remarks, yi.qc_type, yi.remarks, yi.name, yi.assigned_by, yi.shipement_type AS shipment_type, yi.scanning_done_by, CASE WHEN COALESCE(yi.awb_no, ypd.awb) IS NOT NULL AND TRIM(TO_VARCHAR(COALESCE(yi.awb_no, ypd.awb))) <> \'\' AND spf.tracking_no IS NOT NULL THEN \'RAISED\' ELSE \'NOT RAISED\' END AS spf_status, CASE WHEN yi.receiving_date IS NOT NULL AND yi.qc_remarks LIKE \'%Pending%\' AND yi.qc_status LIKE \'pending\' THEN DATEDIFF(DAY, TRY_TO_DATE(yi.receiving_date, \'DD-MM-YYYY\'), CURRENT_DATE) ELSE NULL END AS pendency_ageing, CASE WHEN yi.receiving_date IS NULL OR yi.qc_remarks NOT LIKE \'%Pending%\' OR yi.qc_status NOT LIKE \'pending\' THEN NULL WHEN DATEDIFF(DAY, TRY_TO_DATE(yi.receiving_date, \'DD-MM-YYYY\'), CURRENT_DATE) < 2 THEN \'0-1 days\' WHEN DATEDIFF(DAY, TRY_TO_DATE(yi.receiving_date, \'DD-MM-YYYY\'), CURRENT_DATE) < 5 THEN \'2-4 days\' WHEN DATEDIFF(DAY, TRY_TO_DATE(yi.receiving_date, \'DD-MM-YYYY\'), CURRENT_DATE) < 10 THEN \'5-9 days\' WHEN DATEDIFF(DAY, TRY_TO_DATE(yi.receiving_date, \'DD-MM-YYYY\'), CURRENT_DATE) < 15 THEN \'10-14 days\' WHEN DATEDIFF(DAY, TRY_TO_DATE(yi.receiving_date, \'DD-MM-YYYY\'), CURRENT_DATE) < 20 THEN \'15-19 days\' ELSE \'20+ days\' END AS pendency_ageing_bucket FROM snitch_db.maplemonk.return_2_inwarding_data yi FULL OUTER JOIN snitch_db.maplemonk.predispatch_pre_dispatch ypd ON REGEXP_REPLACE(TRIM(ypd.awb), \'[^[:print:]]\', \'\') = REGEXP_REPLACE(TRIM(yi.awb_no), \'[^[:print:]]\', \'\') LEFT JOIN ( SELECT LOWER(TRIM(TO_VARCHAR(awb))) AS tracking_no FROM spf_b2c_final UNION SELECT LOWER(TRIM(TO_VARCHAR(trackingid))) FROM spf_mp_final UNION SELECT LOWER(TRIM(TO_VARCHAR(returntrackingid))) FROM spf_mp_final ) spf ON LOWER(TRIM(TO_VARCHAR(COALESCE(yi.awb_no, ypd.awb)))) = spf.tracking_no ORDER BY courier_partner_date DESC; CREATE OR REPLACE TABLE ylk_b2c_returns_daily_summary AS ( WITH base AS ( SELECT DATE(receiving_date) AS receiving_date, channel, CASE WHEN channel = \'B2C\' OR channel IS NULL THEN \'D2C\' ELSE \'Marketplace\' END AS channel_type, COUNT(receiving_date) AS received, COUNT(qc_completed_at) AS cleared FROM snitch_db.maplemonk.ylk_b2c_returns WHERE receiving_date IS NOT NULL GROUP BY 1,2 ), pending_calc AS ( SELECT receiving_date, channel, channel_type, received, cleared, SUM(received - cleared) OVER (PARTITION BY channel ORDER BY receiving_date ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS pending_at_start FROM base ) SELECT receiving_date, channel, channel_type, COALESCE(pending_at_start, 0) AS pending_at_start, received, cleared, (COALESCE(pending_at_start, 0) + received - cleared) AS pending FROM pending_calc ORDER BY receiving_date, channel ); CREATE OR REPLACE TABLE ylk_b2c_channel_pendency_2 AS ( WITH base_data AS ( SELECT COALESCE(TRY_TO_DATE(receiving_date, \'DD-MM-YYYY\'), TRY_TO_TIMESTAMP(scanning_date, \'MON DD, YYYY HH:MI PM\')::DATE) AS receiving_date, TYPE AS WH, CASE WHEN CHANEL = \'B2C\' OR CHANEL IS NULL THEN \'D2C\' ELSE \'Marketplace\' END AS channel_type, CASE WHEN qc_remarks = \'Verified UC\' AND TOTE_NUMBER != \'\' THEN COALESCE(TRY_TO_TIMESTAMP(TRIM(TOTE_NUMBER), \'YYYY-MM-DD HH24:MI:SS\'), TRY_TO_TIMESTAMP(TRIM(TOTE_NUMBER), \'YYYY-MM-DD HH24:MI\'), TRY_TO_TIMESTAMP(TRIM(TOTE_NUMBER), \'DD-MM-YYYY HH24:MI:SS\'), TRY_TO_TIMESTAMP(TRIM(TOTE_NUMBER), \'DD-MM-YYYY HH24:MI\')) WHEN qc_remarks = \'Verified UC\' AND TOTE_NUMBER = \'\' THEN TRY_TO_DATE(receiving_date, \'DD-MM-YYYY\') END AS tote_ts, COALESCE(TRY_TO_TIMESTAMP_NTZ(qc_timestamp), TRY_TO_TIMESTAMP_NTZ(TO_VARCHAR(qc_timestamp), \'MON DD, YYYY HH12:MI AM\'), TRY_TO_TIMESTAMP_NTZ(TO_VARCHAR(qc_timestamp), \'MON DD, YYYY HH12:MI:SS AM\'), TRY_TO_TIMESTAMP_NTZ(TO_VARCHAR(qc_timestamp))) AS qc_ts, QC_REMARKS, QC_STATUS FROM snitch_db.maplemonk.return_2_inwarding_data WHERE name <> \'Sankeerth\' AND QC_STATUS != \'Stuck Shipments\' AND COALESCE(TRY_TO_DATE(receiving_date, \'DD-MM-YYYY\'), TRY_TO_TIMESTAMP(scanning_date, \'MON DD, YYYY HH:MI PM\')::DATE) IS NOT NULL AND COALESCE(TRY_TO_DATE(receiving_date, \'DD-MM-YYYY\'), TRY_TO_TIMESTAMP(scanning_date, \'MON DD, YYYY HH:MI PM\')::DATE) >= DATEADD(\'day\', -90, CURRENT_DATE()) ), q1_daily AS ( SELECT receiving_date, WH, channel_type, COUNT(*) AS received FROM base_data GROUP BY 1,2,3 ), q1_agent_daily AS ( SELECT CASE WHEN CAST(qc_ts AS TIME) < \'08:00:00\' THEN DATEADD(DAY, -1, qc_ts::DATE) ELSE qc_ts::DATE END AS receiving_date, WH, channel_type, COUNT(*) AS agent_cleared FROM base_data WHERE QC_REMARKS != \'Verified UC\' AND QC_STATUS = \'Completed by Agent\' AND qc_ts IS NOT NULL GROUP BY 1,2,3 ), q2_cleared AS ( SELECT CASE WHEN CAST(tote_ts AS TIME) < \'08:00:00\' THEN DATEADD(DAY, -1, tote_ts::DATE) ELSE tote_ts::DATE END AS receiving_date, channel_type, WH, SUM(CASE WHEN QC_REMARKS = \'Verified UC\' THEN 1 ELSE 0 END) AS cleared FROM base_data WHERE QC_REMARKS = \'Verified UC\' AND tote_ts IS NOT NULL GROUP BY 1,2,3 ), daily AS ( SELECT cal.receiving_date, cal.channel_type, cal.WH, COALESCE(q1.received, 0) AS received, COALESCE(q2.cleared, 0) AS cleared, COALESCE(q1a.agent_cleared, 0) AS agent_cleared FROM (SELECT receiving_date, WH, channel_type FROM q1_daily UNION SELECT receiving_date, WH, channel_type FROM q2_cleared UNION SELECT receiving_date, WH, channel_type FROM q1_agent_daily) cal LEFT JOIN q1_daily q1 ON cal.receiving_date = q1.receiving_date AND cal.channel_type = q1.channel_type AND cal.WH = q1.WH LEFT JOIN q2_cleared q2 ON cal.receiving_date = q2.receiving_date AND cal.channel_type = q2.channel_type AND cal.WH = q2.WH LEFT JOIN q1_agent_daily q1a ON cal.receiving_date = q1a.receiving_date AND cal.channel_type = q1a.channel_type AND cal.WH = q1a.WH ), final_calc AS ( SELECT receiving_date, channel_type, WH, COALESCE(SUM(received - cleared - agent_cleared) OVER (PARTITION BY channel_type, WH ORDER BY receiving_date ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS pending_at_start, received, cleared, agent_cleared, SUM(received - cleared - agent_cleared) OVER (PARTITION BY channel_type, WH ORDER BY receiving_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS pending FROM daily ) SELECT * FROM final_calc ORDER BY receiving_date, channel_type, WH ); CREATE OR REPLACE TABLE ylk_b2c_missed_predispatch_partners AS WITH inward AS ( SELECT TRY_TO_DATE(receiving_date, \'DD-MM-YYYY\') AS receiving_date, CASE WHEN LOWER(TRIM(lm_patner)) IN (\'express bee\',\'xpressbees\') THEN \'xpressbees\' WHEN LOWER(TRIM(lm_patner)) IN (\'ajio\',\'ajio surface\',\'ajiowo surface\') THEN \'ajio\' WHEN LOWER(TRIM(lm_patner)) IN (\'blitz\',\'blitz (grow simplee)\') THEN \'blitz\' WHEN LOWER(TRIM(lm_patner)) IN (\'bluedart\',\'blue dart\') THEN \'bluedart\' WHEN LOWER(TRIM(lm_patner)) IN (\'delhivery\',\'delhivery surface\') THEN \'delhivery\' WHEN LOWER(TRIM(lm_patner)) IN (\'myntra\',\'direct myntra-fk\') THEN \'myntra\' ELSE LOWER(TRIM(lm_patner)) END AS partner FROM snitch_db.maplemonk.return_2_inwarding_data WHERE receiving_date IS NOT NULL AND lm_patner IS NOT NULL AND LOWER(TRIM(lm_patner)) <> \'sankeerth\' GROUP BY 1,2 ), predispatch AS ( SELECT TRY_TO_DATE(date, \'DD-MM-YYYY\') AS dispatch_date, CASE WHEN LOWER(TRIM(source)) IN (\'express bee\',\'xpressbees\') THEN \'xpressbees\' WHEN LOWER(TRIM(source)) IN (\'ajio\',\'ajio surface\',\'ajiowo surface\') THEN \'ajio\' WHEN LOWER(TRIM(source)) IN (\'blitz\',\'blitz (grow simplee)\') THEN \'blitz\' WHEN LOWER(TRIM(source)) IN (\'bluedart\',\'blue dart\') THEN \'bluedart\' WHEN LOWER(TRIM(source)) IN (\'delhivery\',\'delhivery surface\') THEN \'delhivery\' WHEN LOWER(TRIM(source)) IN (\'myntra\',\'direct myntra-fk\') THEN \'myntra\' ELSE LOWER(TRIM(source)) END AS partner FROM snitch_db.maplemonk.predispatch_pre_dispatch WHERE source IS NOT NULL GROUP BY 1,2 ), joined AS ( SELECT i.receiving_date, i.partner, p.partner AS has_predispatch FROM inward i LEFT JOIN predispatch p ON i.partner = p.partner AND i.receiving_date = p.dispatch_date ) SELECT receiving_date, LISTAGG(partner, \', \') AS missed_partners FROM joined WHERE has_predispatch IS NULL GROUP BY receiving_date ORDER BY receiving_date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            